resource "aws_s3_bucket" "videos" {
  bucket = "my-course-videos-2026"
  tags = {
    project = "courses"
    env     = "prod"
  }
}

resource "aws_s3_bucket_public_access_block" "videos" {
  bucket                  = aws_s3_bucket.videos.id
  block_public_acls       = true
  restrict_public_buckets = true
}
